/bin/zsh -lc "pwd && git log -2 --oneline --decorate && python3 - <<'PY'
import collections,subprocess
def git(*args): return subprocess.check_output(['git',*args]).decode().strip('\\0\\n')
print(git('status','--short','--branch','--untracked-files=normal'))
for args in [('diff','--name-only','-z'),('diff','--cached','--name-only','-z'),('ls-files','--others','--exclude-standard','-z')]:
 items=[v for v in git(*args).split('\\0') if v]
 print(args,len(items))
 if args[0]=='ls-files':
  print(collections.Counter('/'.join(p.split('/')[:4]) for p in items))
for h in ('2304dad','6c041fd'):
 print(h,len(git('diff-tree','--no-commit-id','--name-only','-r','-z',h).split('\\0')))
print('distinct committed',len(git('diff','--name-only','-z','e855ea2..6c041fd').split('\\0')))
PY"
